<?php
if(!defined('ABSPATH')){exit;} final class DSVS_Renderer { public static function error(){return '<p class="dsvs-error">DSVS-Daten momentan nicht verfügbar.</p>';} public static function ranking($ranking,$league){if(!$ranking){return '<p class="dsvs-notice">Für diese Liga konnte keine Rangliste gefunden werden.</p>';}ob_start();?><section class="dsvs-block dsvs-ranking"><?php self::heading($league,'Rangliste Begegnungen');?><div class="dsvs-table-wrap"><table class="dsvs-table"><thead><tr><th>Rang</th><th>Name / Mannschaft</th><th>Beg.</th><th>Gew.</th><th>Verl.</th><th>Quote</th></tr></thead><tbody><?php foreach($ranking as $entry){$highlight=DSVS_Settings::is_highlighted_team($entry['team']);?><tr<?php echo $highlight?' class="dsvs-own-team"':'';?>><td><?php echo esc_html($entry['rank']);?></td><td class="dsvs-ranking-name"><strong><?php echo esc_html($entry['player']);?></strong><?php if($entry['team']!==''){?><br><span><?php echo esc_html($entry['team']);?></span><?php }?></td><td><?php echo esc_html($entry['played']);?></td><td><?php echo esc_html($entry['won']);?></td><td><?php echo esc_html($entry['lost']);?></td><td><strong><?php echo esc_html($entry['quote']);?></strong></td></tr><?php }?></tbody></table></div></section><?php return ob_get_clean();} private static function heading($league,$subtitle){echo '<header class="dsvs-heading"><h2>'.esc_html($league['name']).'</h2><h3>'.esc_html($subtitle).'</h3></header>';} public static function standings($rows,$league){if(!$rows){return '<p class="dsvs-notice">Für diese Liga ist keine Tabelle verfügbar.</p>';}ob_start();?><section class="dsvs-block"><?php self::heading($league,'Tabelle');?><div class="dsvs-table-wrap"><table class="dsvs-table"><thead><tr><?php foreach(array('Platz','Mannschaft','S','G','U','V','Pkt.','Diff.','Partien') as $h){echo '<th>'.esc_html($h).'</th>';}?></tr></thead><tbody><?php foreach($rows as $row){?><tr<?php echo DSVS_Settings::is_highlighted_team($row[1])?' class="dsvs-own-team"':'';?>><?php foreach($row as $cell){echo '<td>'.esc_html($cell).'</td>';}?></tr><?php }?></tbody></table></div></section><?php return ob_get_clean();} public static function games($games,$league,$subtitle,$id='',$live=false){ob_start();?><section <?php echo $id?'id="'.esc_attr($id).'"':'';?> class="dsvs-block dsvs-games" <?php echo $live?'data-dsvs-league="'.esc_attr($league['key']).'"':'';?>><?php self::heading($league,$subtitle);if(!$games){echo '<p>Keine passenden Spiele gefunden.</p>';}else{?><div class="dsvs-table-wrap"><table class="dsvs-table"><thead><tr><th>Termin</th><th>Heim</th><th>Ergebnis</th><th>Gast</th></tr></thead><tbody><?php foreach($games as $game){$own=DSVS_Settings::is_highlighted_team($game['home'])||DSVS_Settings::is_highlighted_team($game['away']);?><tr<?php echo $own?' class="dsvs-own-team"':'';?>><td><?php echo esc_html($game['date'].' '.$game['time']);?></td><td><?php echo esc_html($game['home']);?></td><td class="dsvs-result"><?php echo esc_html($game['result']);?></td><td><?php echo esc_html($game['away']);?></td></tr><?php }?></tbody></table></div><?php }?></section><?php return ob_get_clean();} }
